import {puppets,settings,actions,props,invitations,invitationById,audienceQuestions,sceneCaption} from './loft-content.mjs';
import {loftState,startShow,chooseScene,setScenePart,moveScene,performShow,stepShow,meetAudience,spotlightScene,nextAudienceQuestion,chooseAudienceQuestion,reviseShow,reopenShow,noteLoftAudio,MAX_SCENES,MAX_DIALOGUE,setLoftEditor,setSceneDialogue,addScene,removeScene} from './loft-core.mjs';
import {sceneArt,puppetArt,propArt,backdropArt} from './loft-art.mjs';
import {hearButton} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(attrs,label,kind='secondary',disabled=false)=>`<button type="button" class="${kind}" ${attrs} ${disabled?'disabled':''}>${label}</button>`;
const kept=state=>`<section class="panel"><h2>An earlier theater notebook is kept</h2><p>This version cannot safely change it. Download your notes to keep its original contents; all other destinations remain open.</p><a class="secondary" href="#notes">Grown-up notes and download</a></section>`;
function ideas(draft){return `<details class="loft-ideas" ${draft?'':'open'}><summary>${draft?'Begin another show':'Choose a starting idea'}</summary><p>${draft?'Your current story will go on the shelf. ':''}These are starters. Every scene can change.</p><div class="loft-invitation-strip">${invitations.map(i=>`<button class="loft-invitation" data-loft-start="${i.id}">${sceneArt(i.frames[0],true)}<strong>${i.title}</strong><span>${i.hook}</span></button>`).join('')}</div></details>`;}
function tickets(d,audience=false){return `<label class="loft-scene-picker">${audience?'Choose any scene to discuss':'Scene to work on'}<select ${audience?'data-loft-spotlight-select':'data-loft-scene-select'}>${d.frames.map((f,i)=>`<option value="${i}" ${(audience?d.spotlight??d.stage:d.selected)===i?'selected':''}>Scene ${i+1} · ${esc(puppets.find(p=>p.id===f.actor).name)}</option>`).join('')}</select></label>${audience?button('data-loft-select-spotlight','Bring this scene onto the stage'):''}`;}
const spoken=f=>f.dialogue?`${puppets.find(p=>p.id===f.actor).name} says: ${f.dialogue}`:'';
const sceneText=f=>sceneCaption(f)+(f.dialogue?' '+spoken(f):'');
const dialogue=f=>`<blockquote class="loft-dialogue" ${f.dialogue?'':'hidden'}><strong data-loft-speaker>${esc(puppets.find(p=>p.id===f.actor).name)} says:</strong><span data-loft-spoken-text>${esc(f.dialogue||'')}</span></blockquote>`;
const choiceArt=(part,id)=>part==='actor'?puppetArt(id):part==='place'?backdropArt(id):part==='prop'?propArt(id):`<span class="loft-action-mark" aria-hidden="true">${{finds:'⌕',carries:'➜',offers:'♡',plays:'♫',wonders:'?'}[id]}</span>`;
function editor(d){
 const frame=d.frames[d.selected],parts=[['actor','Who?',puppets],['place','Where?',settings],['action','What happens?',actions],['prop','What to bring?',props]],part=parts[d.choice];
 const prompts=['Who arrives, and what might they say?','What does this puppet want? Could another scene show a response?','What changes along the way? Try a surprise, a problem, or an ending.'];
 const content=d.editor==='pictures'?`<p>Choose ${['a puppet','a place','an action','a prop'][d.choice]} for this scene.</p><fieldset class="loft-picture-step"><legend>${part[1]}</legend><div class="loft-choices">${part[2].map(x=>`<button type="button" class="loft-choice" data-loft-part="${part[0]}" data-loft-value="${x.id}" aria-pressed="${frame[part[0]]===x.id}">${choiceArt(part[0],x.id)}<span>${x.name}</span></button>`).join('')}</div></fieldset><div class="summary-links">${button(`data-loft-choice="${d.choice-1}"`,'Previous picture choice','secondary',d.choice===0)}${d.choice<3?button(`data-loft-choice="${d.choice+1}"`,'Next picture choice','primary'):button('data-loft-editor="words"','Give this puppet words','primary')}</div>`:d.editor==='words'?`<p>What would ${esc(puppets.find(p=>p.id===frame.actor).name)} say? Type, use your keyboard’s dictation, or say it aloud together. Leaving it blank is welcome.</p><label for="loft-dialogue">This puppet’s own words</label><textarea id="loft-dialogue" rows="4" maxlength="${MAX_DIALOGUE}" aria-describedby="loft-word-count loft-word-privacy">${esc(frame.dialogue)}</textarea><p id="loft-word-count" class="tiny">${frame.dialogue.length} / ${MAX_DIALOGUE} keyboard characters</p><p class="loft-kind-note">${prompts[Math.min(2,Math.floor((d.frames.length-1)/3))]}</p><p id="loft-word-privacy" class="tiny">Words stay in this browser with your save settings. Notes downloads include them. Use pretend names if you plan to share a download.</p>${button('data-loft-editor="order"','See how our story fits','primary')}`:`<p>Move this whole scene, including its words, or copy it to make the next moment. A short show is welcome too.</p><div class="summary-links">${button('data-loft-move="-1"','Move earlier','secondary',d.selected===0)}${button('data-loft-move="1"','Move later','secondary',d.selected===d.frames.length-1)}${button('data-loft-add','Add a scene like this','primary',d.frames.length>=MAX_SCENES)}</div><p>${d.frames.length} of ${MAX_SCENES} scene spaces. A copied scene keeps its words; change any part.</p><details class="loft-remove"><summary>Remove this scene…</summary><p>Remove scene ${d.selected+1}, including its words? Keep at least one scene. Close this panel to keep it.</p>${button('data-loft-remove','Yes, remove this scene','secondary',d.frames.length===1)}</details><details><summary>Read our whole story</summary><ol>${d.frames.map(f=>`<li>${esc(sceneCaption(f))}${dialogue(f)}</li>`).join('')}</ol></details>`;
 return `${tickets(d)}<h2 id="loft-edit-title" tabindex="-1">Making scene ${d.selected+1} of ${d.frames.length}</h2><nav class="loft-edit-pages" aria-label="Making steps">${[['pictures','1. Pictures'],['words','2. Puppet words'],['order','3. Story order']].map(([id,label])=>button(`data-loft-editor="${id}" aria-pressed="${d.editor===id}"`,label)).join('')}</nav>${content}<div class="loft-main-actions">${button('data-loft-perform','Perform our show','primary')}<span>${d.frames.length} scenes. You decide when each one changes.</span></div>`;
}
function performance(d){return `<div class="loft-performance-controls"><h2 id="loft-performance-title" tabindex="-1">Scene ${d.stage+1} of ${d.frames.length}</h2><p>Tell it in your own voice, make puppet noises, or use “Hear this scene.” Move on when you’re ready.</p><div class="summary-links">${button('data-loft-step="-1"','Previous scene','secondary',d.stage===0)}${d.stage<d.frames.length-1?button('data-loft-step="1"','Next scene','primary'):button('data-loft-audience','Meet our audience','primary')}${button('data-loft-revise','Back to making','text-button')}</div></div>`;}
function audience(d){const q=audienceQuestions[d.question];return `<section class="loft-audience"><h2 id="loft-audience-title">A question from the front row</h2><p>Our imaginary audience is curious. Every scene is welcome.</p><label for="loft-question">Choose a wondering</label><select id="loft-question">${audienceQuestions.map((q,i)=>`<option value="${i}" ${d.question===i?'selected':''}>${q.title}</option>`).join('')}</select><p class="loft-audience-question">${q.text}</p>${hearButton(q.text,'Hear the audience question')}${tickets(d,true)}${d.spotlight!==null?`<div class="loft-reflection" role="status"><p>You chose scene ${d.spotlight+1}: ${esc(sceneCaption(d.frames[d.spotlight]))}</p><p>Tell someone what you notice, act it out, or draw your idea. You can keep your story just as it is.</p></div>`:'<p class="tiny">Choose a scene, then bring it onto the stage.</p>'}<div class="summary-links">${button('data-loft-change-scene','Change this scene','primary',d.spotlight===null)}${button('data-loft-question-next','Another audience question')}${button('data-loft-perform','Perform again')}${button('data-loft-revise','Back to making','text-button')}</div></section>`;}
function shelf(l){return `<details class="loft-shelf"><summary>Our show shelf</summary><p class="tiny">Your 12 newest shows stay here, plus the one you are working on. Starting a new show puts this one on the shelf.</p>${l.shelf.length?`<div class="loft-shelf-shows">${[...l.shelf].reverse().map(s=>`<button class="loft-saved-show" data-loft-open="${s.id}" ${l.draft?.id===s.id?'disabled':''}>${sceneArt(s.frames[0],true)}<span><strong>Show ${s.id} · ${esc(invitationById(s.invitation).title)}</strong><small>${l.draft?.id===s.id?'On stage now':s.shared?'Saved after a performance':'Saved while making'}${l.draft?.id===s.id?'':' · Open this show'}</small></span></button>`).join('')}</div>`:'<p>Finish a performance or begin another story, and a show will have a place here.</p>'}</details>`;}
export function loftPage(state){
 const l=loftState(state);if(!l)return kept(state);const d=l.draft,index=d?.mode==='edit'?d.selected:d?.stage,frame=d?.frames[index]||invitations[0].frames[0];
 return `<div class="loft-room"><div class="page-heading"><a class="back" href="#home">← Back to the garden</a><h1>Story Loft</h1><a class="secondary" href="#workshop/windows">Read at the Two Windows story desk</a><p>The storm scattered the library puppets. Now our neighbors are ready for a little show. Make a little show, give the puppets words, and add scenes whenever you want.</p>${!d?hearButton('Choose a starting idea. Pick who is in each scene, where they are, what happens, and a prop. Perform your three scenes at your own pace. Every surprising combination is welcome.','Hear how to make a show'):''}</div>${d?.mode==='edit'?'<div class="loft-workbench">':''}<div class="loft-main-stage">${sceneArt(frame)}<p class="loft-caption" id="loft-caption" tabindex="-1">${d?esc(sceneCaption(frame)):'A small stage. A whole world to imagine.'}</p>${d?dialogue(frame)+`<span id="loft-scene-audio">${hearButton(sceneText(frame),'Hear this scene')}</span>`:''}</div>${d?`<div class="loft-making"><p class="loft-starter-note">Starting idea: ${esc(invitationById(d.invitation).title)}. These are starter scenes; keep or change every choice.</p>${d.mode==='edit'?editor(d):d.mode==='perform'?performance(d):audience(d)}</div>`:''}${d?.mode==='edit'?'</div>':''}${ideas(d)}${shelf(l)}<details class="loft-grownups"><summary>Grown-ups: what this little stage practices</summary><p>Choosing characters, settings and events; revisiting a sequence for an audience. Picture captions are supplied. Puppet dialogue is optional learner-authored text, which may be composed with help and is not evaluated. Discussion and off-screen stories are unobserved. This does not assess independent writing, retelling, reading, spelling, or story quality.</p><a href="#notes">Open the private notebook</a></details></div>`;
}
export function loftNotes(state){
 if(!Object.hasOwn(state,'loft'))return '';const l=loftState(state);
 if(!l)return `<details class="panel"><summary>Story Loft: an earlier notebook is kept</summary><p>Unavailable format retained without changes; included in notes downloads.</p><pre>${esc(JSON.stringify(state.loft,null,2))}</pre></details>`;
 const shows=[...l.shelf.filter(s=>s.id!==l.draft?.id),...(l.draft?[l.draft]:[])];
 return `<details class="panel"><summary>Story Loft: picture stories and revision</summary><p>Tap-composed pictures, supplied captions and optional puppet words. Dialogue may be supported; it is not automatically evaluated. Shows, scene edits and requested narration record participation only. No correct/independent score, oral retelling, independent writing proficiency, reading level or discussion response is inferred. Shelf keeps 12 snapshots plus the draft.</p>${shows.map(s=>`<article><h3>Show ${s.id}: ${esc(invitationById(s.invitation).title)}</h3><p>${s.changes} saved changes (including typing), edits and reorders. Current arrangement ${s.shared?'saved after stepping through the performance':'not yet shared through a full performance'}. Narration requested: ${s.heard?'yes':'no'}. ${l.draft?.id===s.id?'Working show.':''}</p><ol>${s.frames.map(f=>`<li>${esc(sceneCaption(f))}${dialogue(f)}</li>`).join('')}</ol></article>`).join('')}<a href="#loft">Return to the little stage</a></details>`;
}
export function bindLoft(state,ctx){
 const change=(fn,selector,animate=false)=>{if(!fn())return;ctx.save();ctx.render();if(animate)document.querySelector('[data-loft-stage]')?.classList.add('loft-acted');if(selector)ctx.focus(selector);};
 document.querySelectorAll('[data-loft-editor]').forEach(b=>b.onclick=()=>change(()=>setLoftEditor(state,b.dataset.loftEditor),'#loft-edit-title'));
 document.querySelectorAll('[data-loft-choice]').forEach(b=>b.onclick=()=>change(()=>setLoftEditor(state,'pictures',Number(b.dataset.loftChoice)),'#loft-edit-title'));
 document.querySelector('[data-loft-scene-select]')?.addEventListener('change',e=>change(()=>chooseScene(state,Number(e.target.value)),'#loft-edit-title'));
 document.querySelector('[data-loft-select-spotlight]')?.addEventListener('click',()=>change(()=>spotlightScene(state,Number(document.querySelector('[data-loft-spotlight-select]').value)),'.loft-reflection'));
 document.querySelector('[data-loft-add]')?.addEventListener('click',()=>change(()=>addScene(state),'#loft-edit-title'));
 document.querySelector('[data-loft-remove]')?.addEventListener('click',()=>change(()=>removeScene(state),'#loft-edit-title'));
 document.querySelector('#loft-dialogue')?.addEventListener('input',e=>{if(!setSceneDialogue(state,e.target.value))return;ctx.save();document.querySelector('#loft-word-count').textContent=`${e.target.value.length} / ${MAX_DIALOGUE} keyboard characters`;const bubble=document.querySelector('.loft-main-stage .loft-dialogue');bubble.hidden=!e.target.value;bubble.querySelector('[data-loft-spoken-text]').textContent=e.target.value;const audio=document.querySelector('#loft-scene-audio [data-speak]');if(audio)audio.dataset.speak=sceneText(loftState(state).draft.frames[loftState(state).draft.selected]);});
 document.querySelectorAll('[data-loft-start]').forEach(b=>b.onclick=()=>change(()=>startShow(state,b.dataset.loftStart),'#loft-edit-title'));
 document.querySelectorAll('[data-loft-scene]').forEach(b=>b.onclick=()=>change(()=>chooseScene(state,Number(b.dataset.loftScene)),'#loft-edit-title'));
 document.querySelectorAll('[data-loft-part]').forEach(b=>b.onclick=()=>change(()=>setScenePart(state,b.dataset.loftPart,b.dataset.loftValue),`[data-loft-part="${b.dataset.loftPart}"][data-loft-value="${b.dataset.loftValue}"]`,true));
 document.querySelectorAll('[data-loft-move]').forEach(b=>b.onclick=()=>change(()=>moveScene(state,Number(b.dataset.loftMove)),'#loft-edit-title'));
 document.querySelectorAll('[data-loft-perform]').forEach(b=>b.onclick=()=>change(()=>performShow(state),'#loft-performance-title',true));
 document.querySelectorAll('[data-loft-step]').forEach(b=>b.onclick=()=>change(()=>stepShow(state,Number(b.dataset.loftStep)),'#loft-performance-title',true));
 document.querySelector('[data-loft-audience]')?.addEventListener('click',()=>change(()=>meetAudience(state),'#loft-audience-title'));
 document.querySelectorAll('[data-loft-spotlight]').forEach(b=>b.onclick=()=>change(()=>spotlightScene(state,Number(b.dataset.loftSpotlight)),'.loft-reflection'));
 document.querySelector('[data-loft-question-next]')?.addEventListener('click',()=>change(()=>nextAudienceQuestion(state),'#loft-audience-title'));
 document.querySelector('#loft-question')?.addEventListener('change',e=>change(()=>chooseAudienceQuestion(state,Number(e.target.value)),'#loft-question'));
 document.querySelector('[data-loft-change-scene]')?.addEventListener('click',()=>change(()=>reviseShow(state,loftState(state)?.draft.spotlight),'#loft-edit-title'));
 document.querySelectorAll('[data-loft-revise]').forEach(b=>b.onclick=()=>change(()=>reviseShow(state),'#loft-edit-title'));
 document.querySelectorAll('[data-loft-open]').forEach(b=>b.onclick=()=>change(()=>reopenShow(state,Number(b.dataset.loftOpen)),'#loft-edit-title'));
 document.querySelectorAll('.loft-room [data-speak]').forEach(b=>b.addEventListener('click',()=>{if(noteLoftAudio(state))ctx.save();}));
}
